// Writes the spellcheck package's English word data, `packages/spellcheck/src/english/en-us-data.ts`,
// from the SCOWL en_US Hunspell files vendored in `packages/spellcheck/vendor/`. Run by hand after
// replacing those files (`npm run vendor:spell-dictionary`); the output is committed and
// `.prettierignore`d, and `spellcheck/dictionary-data.test.ts` fails when the two drift.
import { readFile, writeFile } from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const VENDOR = 'packages/spellcheck/vendor';
export const SPELL_DATA_PATH = 'packages/spellcheck/src/english/en-us-data.ts';

/**
 * The module's text: a legal comment a bundler keeps in a host's build, then the two files as
 * strings.
 * @param {string} aff
 * @param {string} dic
 * @returns {string}
 */
export function renderSpellData(aff, dic) {
	return (
		'/*! en_US Hunspell dictionary from SCOWL 2020.12.07, http://wordlist.sourceforge.net\n' +
		" * Copyright 2000-2018 by Kevin Atkinson; affix file after Geoff Kuenning's Ispell (BSD).\n" +
		' * Notices: THIRD-PARTY-NOTICES.md in @voithos-labs/aragonite-spellcheck. */\n' +
		'// Generated by scripts/vendor/generate-spell-dictionary.mjs; regenerate rather than edit.\n' +
		`export const AFF = ${JSON.stringify(aff)};\n` +
		`export const DIC = ${JSON.stringify(dic)};\n`
	);
}

/** The vendored affix and word files, as text. */
export async function readVendoredDictionary() {
	const [aff, dic] = await Promise.all([
		readFile(path.resolve(VENDOR, 'en-US.aff'), 'utf8'),
		readFile(path.resolve(VENDOR, 'en-US.dic'), 'utf8')
	]);
	return { aff, dic };
}

async function main() {
	const { aff, dic } = await readVendoredDictionary();
	const text = renderSpellData(aff, dic);
	await writeFile(path.resolve(SPELL_DATA_PATH), text, 'utf8');
	console.log(`wrote ${SPELL_DATA_PATH} (${(text.length / 1024).toFixed(0)} KB)`);
}

if (process.argv[1] && fileURLToPath(import.meta.url) === path.resolve(process.argv[1])) {
	main().catch((error) => {
		console.error(error);
		process.exit(1);
	});
}
